import sys
input = sys.stdin.read
data = input().split()

for i in range(0, len(data), 2):
    n = int(data[i])
    s = data[i+1]

    can_be_palindrome = True
    for j in range(n // 2):
        if abs(ord(s[j]) - ord(s[n-1-j])) not in [0, 2]:
            can_be_palindrome = False
            break

    if can_be_palindrome:
        print("YES")
    else:
        print("NO")

